/**
 * Differential support for packed-rule semantics on LMDB: identical data is loaded into an LMDB store and the LMDB
 * answer (cold and warm) is compared against a hand-computed SPARQL bag and against the unoptimized reference
 * evaluation of the parsed algebra over the same stored statements.
 */
final class LmdbPackedRuleDifferentialSupport {

	static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	static final String PREFIXES = "PREFIX : <urn:t:>\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";

	private LmdbPackedRuleDifferentialSupport() {
	}

	static void check(File dir, String turtle, String query, List<String> expected) throws Exception {
		checkAndExplain(dir, turtle, query, expected);
	}

	/**
	 * Runs {@link #check} and returns the optimized plan explanation so callers can additionally assert which rewrite
	 * the planner took (or declined).
	 */
	static String checkAndExplain(File dir, String turtle, String query, List<String> expected) throws Exception {
		SailRepository repository = repository(dir);
		try {
			Model model = Rio.parse(new StringReader(turtle), "urn:t:", RDFFormat.TURTLE);
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(model);
			}
			makeReady(repository);
			String fullQuery = PREFIXES + query;
			List<String> first = evaluate(repository, fullQuery);
			List<String> second = evaluate(repository, fullQuery);
			List<String> reference = reference(repository, fullQuery);
			String plan = explain(repository, fullQuery);
			if (expected != null) {
				List<String> sortedExpected = new ArrayList<>(expected);
				Collections.sort(sortedExpected);
				assertEquals(sortedExpected, reference, "reference oracle disagrees with hand-computed bag");
			}
			assertEquals(reference, first, "LMDB (first run) differs from reference evaluation\n" + plan);
			assertEquals(reference, second, "LMDB (second run) differs from reference evaluation\n" + plan);
			return plan;
		} finally {
			repository.shutDown();
		}
	}

	static SailRepository repository(File dataDir) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setOptimizerSamplingEnabled(false)
				.setBackgroundRawSamplingMaxMillisPerCycle(0L);
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, config));
		repository.init();
		return repository;
	}

	static void makeReady(SailRepository repository) {
		LmdbStore sail = (LmdbStore) repository.getSail();
		SketchBasedJoinEstimator estimator = sail.getBackingStore().getSketchBasedJoinEstimator();
		if (estimator != null) {
			estimator.stop();
			estimator.rebuild();
			LmdbPlannerAwait.awaitEstimatorReady(estimator);
		}
		LmdbPlannerAwait.awaitSketchesReady(sail);
	}

	static String explain(SailRepository repository, String query) {
		try (RepositoryConnection connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
		}
	}

	static List<String> evaluate(SailRepository repository, String query) {
		List<String> rows = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection();
				TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				rows.add(canonical(result.next()));
			}
		}
		Collections.sort(rows);
		return rows;
	}

	static List<String> reference(SailRepository repository, String query) {
		QueryRoot root = new QueryRoot(new SPARQLParser().parseQuery(query, "urn:t:").getTupleExpr());
		List<String> rows = new ArrayList<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			TripleSource source = new TripleSource() {
				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
					return connection.getStatements(subject, predicate, object, false, contexts);
				}

				@Override
				public ValueFactory getValueFactory() {
					return VF;
				}
			};
			try (CloseableIteration<BindingSet> result = new StrictEvaluationStrategy(source, null).precompile(root)
					.evaluate(EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					rows.add(canonical(result.next()));
				}
			}
		}
		Collections.sort(rows);
		return rows;
	}

	static String canonical(BindingSet bindings) {
		TreeMap<String, String> sorted = new TreeMap<>();
		for (String name : bindings.getBindingNames()) {
			Value value = bindings.getValue(name);
			if (value != null) {
				sorted.put(name, value.isLiteral() ? literal((Literal) value) : value.stringValue());
			}
		}
		StringBuilder builder = new StringBuilder();
		sorted.forEach((name, value) -> {
			if (builder.length() > 0) {
				builder.append('|');
			}
			builder.append(name).append('=').append(value);
		});
		return builder.toString();
	}

	private static String literal(Literal literal) {
		if (literal.getLanguage().isPresent()) {
			return "\"" + literal.getLabel() + "\"@" + literal.getLanguage().get();
		}
		if (XSD.STRING.equals(literal.getDatatype())) {
			return "\"" + literal.getLabel() + "\"";
		}
		if (XSD.INTEGER.equals(literal.getDatatype())) {
			return literal.getLabel();
		}
		return "\"" + literal.getLabel() + "\"^^" + literal.getDatatype().stringValue();
	}
}
